    async def renew(
        self,
        code: str,
        *,
        reference: Optional[str] = None,
        extra_headers: Optional[Mapping[str, str]] = None,
        extra_query: Optional[Mapping[str, Any]] = None,
        extra_body: Optional[Mapping[str, Any]] = None,
        timeout: Union[float, httpx.Timeout, None] = None,
        max_retries: Optional[int] = None,
    ) -> Write[BidResult]:
        """Renew a bid.

        Put one of your bids back on the market for 90 days at the same price, quantity and
        currency: an expired or cancelled bid, or a live bid in its last 7 days.

        **To change the price as well, change the bid.** Renewing keeps the bid exactly as it
        was. To reprice a live bid, PATCH /bids/{code} instead: that also runs it for 90 days
        from the change.

        **Which bids can be renewed.** renewable on the bid says whether this endpoint takes it:
        an expired or cancelled bid, or a live one with 7 days or fewer left, with nothing
        matched. Others get TRADE_REFUSED — for a partly matched bid, place a new one for the
        rest. So, even if renewable, does a bid from another venue, an account that cannot bid,
        or a bid over your allowance on its site.

        Scope: bids:write.

        A partner credential's write runs at once and returns the result in .result; a connected
        app's is staged, with the code to confirm in .confirmation.

        Args:
            code: The bid’s opaque code, from GET /bids. URL-encode it as a single path segment.
            reference: Your idempotency key: letters and digits, then . _ : or - allowed.
                Required on a partner credential’s write and kept for good, so a retry with it
                can never act twice. Ignored for connected apps.
            extra_headers: Headers to add to, or replace, the SDK's own, for this call only.
            extra_query: Query parameters this version does not know yet, sent as given.
            extra_body: Body fields this version does not know yet, sent as given.
            timeout: Seconds, or an httpx.Timeout, for this call only. None keeps the client's.
            max_retries: Retries after the first attempt, for this call only. None keeps the
                client's.
        """
        return await self._client._call(
            _RENEW_BID,
            {'code': code},
            body={'reference': reference},
            extra_headers=extra_headers,
            extra_query=extra_query,
            extra_body=extra_body,
            timeout=timeout,
            max_retries=max_retries,
        )
